        const b = project(world, x + 2, 0.6, z, cx, cy, focal);
        const c = project(world, x + 2, 0.6, z + 14, cx, cy, focal);
        const e = project(world, x - 2, 0.6, z + 14, cx, cy, focal);
        if (a && b && c && e) {
          ctx.fillStyle = '#f2f2e8';
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.lineTo(c.x, c.y);
          ctx.lineTo(e.x, e.y);
