function drawRings(ctx, world, cx, cy, focal) {
  const target = nextRing(world);
  for (let i = world.ringIndex; i < world.rings.length; i += 1) {
    const ring = world.rings[i];
    const p = project(world, ring.x, ring.y, ring.z, cx, cy, focal);
    if (!p) continue;
